export function authorizeAI(role:string){if(!['hr_admin','hr_staff','manager'].includes(role))throw new SafeError('Akses Ms. Phali tersedia untuk Admin SDM, Staf HR, dan Manajer.',403)}
export async function context(req:Request){if(req.method!=='POST')throw new SafeError('Metode tidak didukung.',405);const jwt=req.headers.get('Authorization');if(!jwt?.startsWith('Bearer '))throw new SafeError('Silakan masuk kembali.',401);const url=Deno.env.get('SUPABASE_URL')!,anon=Deno.env.get('SUPABASE_ANON_KEY')!;const user=createClient(url,anon,{global:{headers:{Authorization:jwt}}});const{data:{user:auth},error}=await user.auth.getUser();if(error||!auth)throw new SafeError('Sesi tidak valid.',401);const{data:profile,error:pe}=await user.from('profiles').select('role').eq('id',auth.id).single();if(pe||!profile)throw new SafeError('Profil tidak tersedia.',403);authorizeAI(profile.role);const service=createClient(url,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);const{data:ok,error:rateError}=await service.rpc('admit_ai',{p_user:auth.id});if(rateError)throw new SafeError('Layanan AI belum tersedia.',503);if(!ok)throw new SafeError('Batas 20 permintaan per jam tercapai. Coba lagi nanti.',429);return{user,service,id:auth.id,role:profile.role};}
